var m = String(data.lookback || '1h').match(/^(\d+)([smhd])$/);
if (!m) { throw new Error('lookback must look like 30m, 1h or 6h, got: ' + data.lookback); }
var unitMs = { s: 1000, m: 60000, h: 3600000, d: 86400000 }[m[2]];
var end = new Date();
var start = new Date(end.getTime() - (parseInt(m[1], 10) * unitMs));
function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
({
  start_iso: iso(start),
  end_iso: iso(end),
  start_ms: start.getTime(),
  end_ms: end.getTime(),
  lookback: data.lookback
})

