var found = [];
try { found = JSON.parse(data.instances || '[]') || []; } catch (e) { found = []; }
if (!found.length) {
  throw new Error('No EC2 instance matched instance_id="' + data.requested_instance_id +
    '" application="' + data.application + '". Check the region, the instance ID, or the Name tag.');
}
found.sort(function (a, b) { return String(a.InstanceId).localeCompare(String(b.InstanceId)); });
var primary = found[0];
({
  instance_id: primary.InstanceId,
  name: primary.Name || '',
  state: primary.State || '',
  state_reason: primary.StateReason || '',
  instance_type: primary.Type || '',
  availability_zone: primary.Az || '',
  private_ip: primary.PrivateIp || '',
  public_ip: primary.PublicIp || '',
  launch_time: primary.LaunchTime || '',
  matched_count: found.length,
  matched: found
})

var groups = [];
try { groups = JSON.parse(data.groups || '[]') || []; } catch (e) { groups = []; }
groups.sort(function (a, b) { return String(a.Arn).localeCompare(String(b.Arn)); });
groups.slice(0, 10).map(function (g) { return g.Arn; });

function parse(raw, fallback) {
  if (raw === null || raw === undefined || String(raw).trim() === '') { return fallback; }
  if (typeof raw === 'object') { return raw; }
  try { return JSON.parse(raw); } catch (e) { return fallback; }
}
function ran(state) { return String(state).toLowerCase() === 'completed'; }

var instance = parse(data.instance, {});
var checks = [];
var findings = [];
function check(name, state, note) { checks.push({ check: name, status: state, note: note || '' }); }
function finding(severity, check_name, detail) { findings.push({ severity: severity, check: check_name, detail: detail }); }

// --- instance state -------------------------------------------------
var state = String(instance.state || 'unknown');
check('instance_state', state === 'running' ? 'ok' : 'problem', 'state=' + state);
if (state !== 'running') {
  finding('critical', 'instance_state',
    'EC2 instance ' + instance.instance_id + ' is ' + state +
    (instance.state_reason ? ' (' + instance.state_reason + ')' : ''));
}

// --- EC2 status checks ----------------------------------------------
if (ran(data.instance_status_state)) {
  var statuses = parse(data.instance_status_raw, []);
  var s = statuses.length ? statuses[0] : null;
  if (s) {
    var sysOk = String(s.SystemStatus) === 'ok';
    var instOk = String(s.InstanceStatus) === 'ok';
    check('ec2_status_checks', sysOk && instOk ? 'ok' : 'problem',
      'system=' + s.SystemStatus + ' instance=' + s.InstanceStatus);
    if (!sysOk) { finding('critical', 'ec2_status_checks', 'System status check is ' + s.SystemStatus + ' (host/hypervisor level).'); }
    if (!instOk) { finding('critical', 'ec2_status_checks', 'Instance status check is ' + s.InstanceStatus + ' (guest OS / network level).'); }
    if (s.Events && s.Events.length) {
      finding('warning', 'ec2_status_checks', 'AWS has ' + s.Events.length + ' scheduled event(s) for this instance.');
    }
  } else {
    check('ec2_status_checks', 'unavailable', 'describe-instance-status returned no rows');
  }
} else {
  check('ec2_status_checks', 'unavailable', 'collector did not run (' + data.instance_status_state + ')');
}

// --- CloudWatch alarms ----------------------------------------------
if (ran(data.alarms_state)) {
  var alarms = parse(data.alarms_raw, []);
  var app = String(data.application || '');
  var mine = alarms.filter(function (a) {
    var hit = (a.Dimensions || []).some(function (d) { return String(d.Value) === String(instance.instance_id); });
    if (!hit && app) { hit = String(a.Name || '').indexOf(app) !== -1; }
    return hit;
  });
  check('cloudwatch_alarms', mine.length ? 'problem' : 'ok',
    mine.length + ' of ' + alarms.length + ' region alarms in ALARM relate to this target');
  mine.forEach(function (a) {
    finding('critical', 'cloudwatch_alarms', 'Alarm "' + a.Name + '" is in ALARM: ' + a.Reason);
  });
} else {
  check('cloudwatch_alarms', 'unavailable', 'collector did not run (' + data.alarms_state + ')');
}

// --- CPU --------------------------------------------------------------
var cpuMax = null;
if (ran(data.cpu_state)) {
  var cpu = parse(data.cpu_raw, {});
  var pts = cpu.Datapoints || [];
  if (pts.length) {
    cpuMax = pts.reduce(function (m, p) { return Math.max(m, p.Maximum || 0); }, 0);
    check('cpu_utilization', cpuMax >= 90 ? 'problem' : 'ok', 'max=' + cpuMax.toFixed(1) + '% over ' + pts.length + ' datapoints');
    if (cpuMax >= 90) { finding('warning', 'cpu_utilization', 'CPU peaked at ' + cpuMax.toFixed(1) + '% in the lookback window.'); }
  } else {
    check('cpu_utilization', 'unavailable', 'no CloudWatch datapoints in the window');
  }
} else {
  check('cpu_utilization', 'unavailable', 'collector did not run (' + data.cpu_state + ')');
}

// --- StatusCheckFailed metric -----------------------------------------
if (ran(data.status_check_state)) {
  var sc = parse(data.status_check_raw, {});
  var scPts = sc.Datapoints || [];
  var failed = scPts.reduce(function (n, p) { return n + (p.Sum || 0); }, 0);
  if (scPts.length) {
    check('status_check_metric', failed > 0 ? 'problem' : 'ok', failed + ' failed status-check periods');
    if (failed > 0) { finding('critical', 'status_check_metric', 'StatusCheckFailed fired in ' + failed + ' period(s) during the window.'); }
  } else {
    check('status_check_metric', 'unavailable', 'no CloudWatch datapoints in the window');
  }
} else {
  check('status_check_metric', 'unavailable', 'collector did not run (' + data.status_check_state + ')');
}

// --- load balancer target health ---------------------------------------
var allGroups = parse(data.target_groups, []);
var lbRows = parse(data.lb_health, []);
var registered = [];
lbRows.forEach(function (row) {
  if (!row) { return; }
  var targets = parse(row.targets, []);
  targets.forEach(function (t) {
    if (String(t.Id) === String(instance.instance_id)) {
      registered.push({ target_group: row.arn, port: t.Port, state: t.State, reason: t.Reason, description: t.Description });
    }
  });
});
if (!lbRows.length) {
  check('lb_target_health', 'not_applicable', 'no instance-type target groups scanned');
} else if (!registered.length) {
  check('lb_target_health', 'not_applicable', 'instance is not registered in any of the ' + lbRows.length + ' target group(s) scanned');
} else {
  var unhealthy = registered.filter(function (r) { return String(r.state) !== 'healthy'; });
  check('lb_target_health', unhealthy.length ? 'problem' : 'ok',
    registered.length + ' registration(s), ' + unhealthy.length + ' not healthy');
  unhealthy.forEach(function (r) {
    finding('critical', 'lb_target_health',
      'Target ' + instance.instance_id + ':' + r.port + ' in ' + r.target_group + ' is ' + r.state +
      (r.reason ? ' (' + r.reason + (r.description ? ': ' + r.description : '') + ')' : ''));
  });
}

// --- application logs ---------------------------------------------------
var logSamples = [];
if (!String(data.log_group || '')) {
  check('application_logs', 'not_configured', 'no log_group supplied');
} else if (ran(data.app_logs_state)) {
  logSamples = parse(data.app_logs_raw, []);
  check('application_logs', logSamples.length ? 'problem' : 'ok',
    logSamples.length + ' line(s) matching the filter in ' + data.log_group);
  if (logSamples.length) {
    finding('warning', 'application_logs',
      logSamples.length + ' log line(s) matched "' + data.log_group + '" in the window. First: ' +
      String(logSamples[0].Message || '').slice(0, 300));
  }
} else {
  check('application_logs', 'unavailable', 'collector did not run (' + data.app_logs_state + ')');
}

// --- host evidence -------------------------------------------------------
var host = { metrics: {}, sections: {} };
if (String(data.collect_host_evidence || '') !== 'true') {
  check('host_evidence', 'not_configured', 'collect_host_evidence is off');
} else if (String(data.host_state).toLowerCase() !== 'completed') {
  check('host_evidence', 'unavailable', 'SSM collector did not run (' + data.host_state + ')');
} else {
  var text = String(data.host_raw || '');
  text.split(/===(METRIC|SECTION):/).forEach(function (part, i, arr) {
    if (part !== 'METRIC' && part !== 'SECTION') { return; }
    var body = arr[i + 1] || '';
    var nl = body.indexOf('\n');
    if (nl === -1) { return; }
    var key = body.slice(0, nl).replace(/===$/, '').trim();
    var value = body.slice(nl + 1).trim();
    if (part === 'METRIC') { host.metrics[key] = value; } else { host.sections[key] = value; }
  });
  var failedUnits = parseInt(host.metrics.failed_units || '0', 10);
  var diskPct = parseInt(host.metrics.disk_max_pct || '0', 10);
  var svc = host.metrics.app_service_state || 'not_checked';
  // no_such_unit means the application is not packaged as a systemd unit named
  // after itself, which is ordinary — reporting it as a down service would be a
  // false critical on every instance that runs its app any other way.
  var svcDown = svc !== 'active' && svc !== 'not_checked' && svc !== 'no_such_unit';
  var hostProblem = failedUnits > 0 || diskPct >= 90 || svcDown;
  check('host_evidence', hostProblem ? 'problem' : 'ok',
    'failed_units=' + failedUnits + ' max_disk=' + diskPct + '% service=' + svc);
  if (failedUnits > 0) { finding('warning', 'host_evidence', failedUnits + ' systemd unit(s) in a failed state.'); }
  if (diskPct >= 90) { finding('warning', 'host_evidence', 'A filesystem is ' + diskPct + '% full.'); }
  if (svcDown) {
    finding('critical', 'host_evidence', 'Service "' + data.application + '" is ' + svc + ' on the instance.');
  }
}

// --- dependency connectivity ----------------------------------------------
var deps = [];
if (!String(data.dependency_endpoints || '')) {
  check('dependency_connectivity', 'not_configured', 'no dependency_endpoints supplied');
} else if (String(data.deps_state).toLowerCase() !== 'completed') {
  check('dependency_connectivity', 'unavailable', 'SSM probe did not run (' + data.deps_state + ')');
} else {
  String(data.deps_raw || '').split('\n').forEach(function (line) {
    var parts = line.trim().split(/\s+/);
    if (parts.length < 2) { return; }
    deps.push({ endpoint: parts[0], status: parts[1], detail: parts.slice(2).join(' ') });
  });
  var down = deps.filter(function (d) { return d.status !== 'ok'; });
  check('dependency_connectivity', down.length ? 'problem' : 'ok',
    deps.length + ' endpoint(s) probed, ' + down.length + ' unreachable');
  down.forEach(function (d) {
    finding('critical', 'dependency_connectivity', 'Dependency ' + d.endpoint + ' unreachable from the instance (' + d.detail + ').');
  });
}

// --- verdict ----------------------------------------------------------------
var rank = { critical: 0, warning: 1 };
findings.sort(function (a, b) { return rank[a.severity] - rank[b.severity]; });
var criticals = findings.filter(function (f) { return f.severity === 'critical'; }).length;
var warnings = findings.length - criticals;
var unavailable = checks.filter(function (c) { return c.status === 'unavailable'; }).length;
var status;
if (criticals > 0) { status = 'critical'; }
else if (warnings > 0) { status = 'degraded'; }
else if (unavailable > 0) { status = 'inconclusive'; }
else { status = 'healthy'; }

({
  status: status,
  summary: status === 'healthy'
    ? 'No problem signals found across ' + checks.length + ' checks.'
    : criticals + ' critical and ' + warnings + ' warning finding(s) across ' + checks.length + ' checks' +
      (unavailable ? '; ' + unavailable + ' check(s) could not be collected.' : '.'),
  incident_context: data.incident_context,
  target: {
    instance_id: instance.instance_id,
    name: instance.name,
    application: data.application,
    state: instance.state,
    instance_type: instance.instance_type,
    availability_zone: instance.availability_zone,
    private_ip: instance.private_ip,
    public_ip: instance.public_ip,
    launch_time: instance.launch_time,
    region: data.region,
    matched_instances: instance.matched_count
  },
  window: parse(data.window, {}),
  findings: findings,
  checks: checks,
  coverage: {
    total: checks.length,
    collected: checks.length - unavailable,
    unavailable: unavailable,
    target_groups_found: allGroups.length,
    target_groups_scanned: lbRows.length,
    target_groups_truncated: allGroups.length > lbRows.length
  },
  evidence: {
    cpu_max_percent: cpuMax,
    lb_registrations: registered,
    log_samples: logSamples.slice(0, 10),
    dependency_probes: deps,
    host_metrics: host.metrics,
    host_sections: host.sections
  }
})

